insert into public.modules (id, org_id, product_sku, order_index, title, description) values
  ('5e7c67b5-e24d-5478-9bbd-b8920f1fb92d', '6cf541c4-f870-5858-a49c-3b2de28ba050', 'recordings', 0, 'Onboarding & Workspace Setup', 'Orientation, tools provisioning, development environments, and community protocols.'),
  ('1c4d32ba-20e8-5dd6-ac61-ef0f1b98313e', '6cf541c4-f870-5858-a49c-3b2de28ba050', 'recordings', 1, 'AI Foundations & Engineering Mindset', 'Deep dive into LLM mechanics, tokenization, context windows, and deterministic prompting techniques.'),
  ('1fbf40f2-7546-5b34-8ffd-324654424151', '6cf541c4-f870-5858-a49c-3b2de28ba050', 'recordings', 2, 'Automation with n8n', 'Orchestrating production workflows, webhooks, error handlers, and LLM nodes with self-hosted n8n.'),
  ('65d832f1-11ca-52d3-88dc-3a6991b8d4c8', '6cf541c4-f870-5858-a49c-3b2de28ba050', 'recordings', 3, 'Building Autonomous AI Agents', 'State machines, function calling, tool execution, multi-agent coordination, and memory architectures.'),
  ('97142077-2f69-5e30-8e44-237aca830dc7', '6cf541c4-f870-5858-a49c-3b2de28ba050', 'recordings', 4, 'RAG in Practice — Production Retrieval', 'Vector embeddings, chunking strategies, hybrid search (BM25 + cosine), reranking, and enterprise document QA.'),
