insert into public.lessons (id, org_id, module_id, order_index, title, description, bunny_video_id, duration_seconds, is_free_preview, published_at) values
  ('425d9a46-75c8-57df-a1c0-38c152eb8ed1', '6cf541c4-f870-5858-a49c-3b2de28ba050', '5e7c67b5-e24d-5478-9bbd-b8920f1fb92d', 1, 'Platform Overview, Community Guidelines & Tool Stack', 'Introduction to our learning platform, Telegram workspace, API access keys, and project milestones.', 'f6b219a1-081b-411a-8c9e-2e4a81d11100', 2400, false, now()),
  ('00d1632d-aa3c-5b88-942a-6717c608d55c', '6cf541c4-f870-5858-a49c-3b2de28ba050', '5e7c67b5-e24d-5478-9bbd-b8920f1fb92d', 2, 'Local Environment, Node.js, Python & Cloud Sandboxes', 'Setting up clean environments, secure token management, and containerized development tools.', 'f6b219a1-081b-411a-8c9e-2e4a81d11101', 2700, false, now()),
  ('13048d6a-a4f2-52c3-8c28-1cba977feed4', '6cf541c4-f870-5858-a49c-3b2de28ba050', '1c4d32ba-20e8-5dd6-ac61-ef0f1b98313e', 1, 'Fundamentals of AI', 'How modern transformer models think, embeddings, temperature, latency considerations, and practical model benchmarking.', '7a119bc2-31fa-4f90-84cf-ea8547c94b01', 5700, true, now()),
  ('73779c06-cb8a-5c13-8a93-80028f446285', '6cf541c4-f870-5858-a49c-3b2de28ba050', '1c4d32ba-20e8-5dd6-ac61-ef0f1b98313e', 2, 'Prompting & Content Generation', 'System prompts, few-shot examples, JSON schema enforcement, reasoning scaffolds, and anti-hallucination techniques.', '7a119bc2-31fa-4f90-84cf-ea8547c94b02', 5400, false, now()),
  ('959a58bf-6496-5d4c-96f0-363ee25694d5', '6cf541c4-f870-5858-a49c-3b2de28ba050', '1c4d32ba-20e8-5dd6-ac61-ef0f1b98313e', 3, 'Prompting Pt 2 — Structured Extraction & Chains', 'Extracting clean structured data from noisy PDF invoices, receipts, and multi-turn conversations.', '7a119bc2-31fa-4f90-84cf-ea8547c94b03', 6600, false, now()),
  ('58cf56ff-8250-5fcc-9fab-2d4e97f27fee', '6cf541c4-f870-5858-a49c-3b2de28ba050', '1fbf40f2-7546-5b34-8ffd-324654424151', 1, 'Foundations of AI Automation & n8n', 'Deploying n8n instances, understanding webhook triggers, node data schemas, and credentials vaults.', '3c8901fe-5f72-4d22-9018-09acde330101', 5700, false, now()),
  ('03434da3-a946-5919-ac84-2f9e8f2c82bc', '6cf541c4-f870-5858-a49c-3b2de28ba050', '1fbf40f2-7546-5b34-8ffd-324654424151', 2, 'AI-Powered Email Response System', 'End-to-end automated inbox manager with sentiment analysis, CRM lookup, draft generation, and human-in-the-loop approval.', '3c8901fe-5f72-4d22-9018-09acde330102', 7200, false, now()),
  ('1e3ddbef-df6b-55b8-9b86-defd67de1853', '6cf541c4-f870-5858-a49c-3b2de28ba050', '65d832f1-11ca-52d3-88dc-3a6991b8d4c8', 1, 'Calendar Agent Pt 1 — Natural Language Scheduling', 'Constructing custom function calling schemas for Google Calendar API with timezone handling for West Africa (WAT).', '98d5c412-11ae-4cb8-bdf2-f8c6e3990301', 6000, false, now()),
  ('e2ff48ab-2502-59e8-bb8a-f340ac3dd33a', '6cf541c4-f870-5858-a49c-3b2de28ba050', '65d832f1-11ca-52d3-88dc-3a6991b8d4c8', 2, 'Calendar Agent Pt 2 — Conflict Resolution & Multi-Party Invites', 'Handling edge cases, overlapping invite proposals, and resilient retry loops without infinite hallucination.', '98d5c412-11ae-4cb8-bdf2-f8c6e3990302', 6900, false, now()),
  ('489318b9-ab81-55b7-b554-9df3f8a3ea01', '6cf541c4-f870-5858-a49c-3b2de28ba050', '65d832f1-11ca-52d3-88dc-3a6991b8d4c8', 3, 'Agent Architectures, RAG & Context Engineering', 'Comparing ReAct, Plan-and-Solve, and LangGraph architectures. Managing sliding conversation memory cost-effectively.', '98d5c412-11ae-4cb8-bdf2-f8c6e3990303', 7500, false, now()),
  ('458d0623-f783-5fbc-b73e-01e5dbfd3b09', '6cf541c4-f870-5858-a49c-3b2de28ba050', '97142077-2f69-5e30-8e44-237aca830dc7', 1, 'RAG Agent & Pipeline Pt 1 — Ingestion & Chunking', 'Parsing PDF contracts, semantic chunking boundaries, and pushing embeddings to Pinecone and pgvector.', '5420ac88-99ee-471a-9cd4-325ea8290401', 6900, false, now()),
  ('9eca3c55-beb8-54f1-8079-22cc451f1d83', '6cf541c4-f870-5858-a49c-3b2de28ba050', '97142077-2f69-5e30-8e44-237aca830dc7', 2, 'RAG Agent & Pipeline Pt 2 — Retrieval, Reranking & Evaluation', 'Implementing Cohere/BGE rerankers, contextual query rewrites, hallucination guards, and evaluation metrics.', '5420ac88-99ee-471a-9cd4-325ea8290402', 7800, false, now()),
  ('5eda76ad-e0a7-53d4-acf7-a9f5625bad53', '6cf541c4-f870-5858-a49c-3b2de28ba050', '6852ca4e-8d7c-51b2-8161-1d9124728665', 1, 'Website & Chatbot with Lovable + n8n', 'Rapidly prototyping full-stack landing pages and dynamic conversational front-ends synced with n8n webhooks.', '1a980dd3-7621-4f55-88ab-f05cb2910501', 6300, false, now()),
  ('ba7c597c-ee6d-51a5-9bf5-c9302133866c', '6cf541c4-f870-5858-a49c-3b2de28ba050', '6852ca4e-8d7c-51b2-8161-1d9124728665', 2, 'Vibe Coding Pt 1 — Rapid Prototyping & Architecture', 'Supercharging software development using modern AI coding agents, prompt specification files, and component scaffolding.', '1a980dd3-7621-4f55-88ab-f05cb2910502', 6000, false, now()),
  ('3ee28147-6e94-5e3e-9dc4-4ddbd0bba1f8', '6cf541c4-f870-5858-a49c-3b2de28ba050', '6852ca4e-8d7c-51b2-8161-1d9124728665', 3, 'Vibe Coding Pt 2 — Production Hardening & Deployment', 'Taking prototype applications through TypeScript type safety, error boundaries, rate limiting, and global CDN deployment.', '1a980dd3-7621-4f55-88ab-f05cb2910503', 7200, false, now())
