  ('a73559ef-ae1b-5d40-93dd-0504331d0e00', '6cf541c4-f870-5858-a49c-3b2de28ba050', '97142077-2f69-5e30-8e44-237aca830dc7', '458d0623-f783-5fbc-b73e-01e5dbfd3b09', 'Nigerian Regulatory & Financial Documents Corpus (Sample RAG Dataset)', 'Cleaned JSONL evaluation dataset containing 400+ indexed regulatory circulars and financial clauses for RAG testing.', 'dataset', 'JSONL', 'resources/res-7.jsonl', 4300000),
  ('a042759e-d72b-5451-9359-641781234075', '6cf541c4-f870-5858-a49c-3b2de28ba050', '6852ca4e-8d7c-51b2-8161-1d9124728665', '5eda76ad-e0a7-53d4-acf7-a9f5625bad53', 'Lovable Full-Stack AI Webapp Starter & Vibe Coding Prompt Guide', 'Pre-configured Tailwind + React front-end template with webhook connectors and step-by-step vibe coding prompts.', 'code', 'ZIP', 'resources/res-8.zip', 3774873),
  ('bd8cf9f1-0a45-5d87-83f8-07dee828a154', '6cf541c4-f870-5858-a49c-3b2de28ba050', '1c4d32ba-20e8-5dd6-ac61-ef0f1b98313e', '73779c06-cb8a-5c13-8a93-80028f446285', 'AI Foundations & Prompt Architecture Cheat Sheet', 'Quick reference guide for system instructions, JSON schema constraints, reasoning tags, and few-shot formatting.', 'doc', 'PDF', 'resources/res-9.pdf', 2202009)
